/* ========================================
   GlobalStone — Global Commercial Real Estate Services
   Corporate Design System
   ======================================== */

/* CSS Custom Properties */
:root {
  --primary-dark: #0A1628;
  --primary-green: #003F2D;
  --dark-teal: #012A2D;
  --accent-gold: #C9A227;
  --accent-teal: #0D7377;
  --neutral-light: #E6E6E6;
  --neutral-gray: #8A8F94;
  --neutral-dark-gray: #4A4F54;
  --white: #FFFFFF;
  --off-white: #F5F5F5;
  --border-light: #D1D5DB;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  --shadow-sm: 0 1px 2px rgba(10, 22, 40, 0.05);
  --shadow-md: 0 4px 12px rgba(10, 22, 40, 0.08);
  --shadow-lg: 0 12px 32px rgba(10, 22, 40, 0.12);
  --shadow-xl: 0 24px 48px rgba(10, 22, 40, 0.16);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--primary-dark);
  background-color: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.2;
  color: var(--primary-dark);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--neutral-dark-gray);
}

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }

.font-sans { font-family: var(--font-sans); }
.font-serif { font-family: var(--font-serif); }

.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

.uppercase { text-transform: uppercase; letter-spacing: 0.05em; }

/* Layout Utilities */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

.section-padding {
  padding-top: 4rem;
  padding-bottom: 4rem;
}

@media (min-width: 768px) {
  .section-padding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
}

@media (min-width: 1024px) {
  .section-padding {
    padding-top: 6rem;
    padding-bottom: 6rem;
  }
}

/* Grid */
.grid {
  display: grid;
  gap: 1.5rem;
}

.grid-2 { grid-template-columns: repeat(1, 1fr); }
.grid-3 { grid-template-columns: repeat(1, 1fr); }
.grid-4 { grid-template-columns: repeat(1, 1fr); }
.grid-6 { grid-template-columns: repeat(1, 1fr); }

@media (min-width: 640px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 768px) {
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
}

/* Flex */
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-2 { gap: 0.5rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-8 { gap: 2rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 2px;
  transition: all var(--transition-base);
  cursor: pointer;
}

.btn-primary {
  background-color: var(--accent-gold);
  color: var(--primary-dark);
}

.btn-primary:hover {
  background-color: #B8941F;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background-color: transparent;
  color: var(--white);
  border: 1px solid var(--white);
}

.btn-secondary:hover {
  background-color: var(--white);
  color: var(--primary-dark);
}

.btn-dark {
  background-color: var(--primary-dark);
  color: var(--white);
}

.btn-dark:hover {
  background-color: var(--dark-teal);
}

.btn-outline-dark {
  background-color: transparent;
  color: var(--primary-dark);
  border: 1px solid var(--primary-dark);
}

.btn-outline-dark:hover {
  background-color: var(--primary-dark);
  color: var(--white);
}

/* Cards */
.card {
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: 2px;
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-body {
  padding: 1.5rem;
}

/* ========================================
   HEADER & NAVIGATION
   ======================================== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background-color: var(--white);
  border-bottom: 1px solid var(--border-light);
  transition: box-shadow var(--transition-base);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--accent-gold);
}

/* Desktop Navigation */
.nav-desktop {
  display: none;
}

@media (min-width: 1024px) {
  .nav-desktop {
    display: flex;
    align-items: center;
    gap: 2rem;
  }
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--primary-dark);
  padding: 0.5rem 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--accent-gold);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

.nav-link:hover {
  color: var(--accent-gold);
}

/* Mega Menu */
.mega-menu-trigger {
  position: relative;
}

.mega-menu {
  position: absolute;
  top: calc(100% + 1px);
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  width: 720px;
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: 2px;
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
  padding: 2rem;
}

.mega-menu-trigger:hover .mega-menu,
.mega-menu-trigger.active .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 2rem;
}

.mega-menu-title {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--neutral-gray);
  margin-bottom: 1rem;
}

.mega-menu-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.mega-menu-item {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--primary-dark);
  padding: 0.5rem 0;
  transition: color var(--transition-fast);
}

.mega-menu-item:hover {
  color: var(--accent-gold);
}

/* Mobile Navigation */
.nav-mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--primary-dark);
  transition: all var(--transition-base);
}

.nav-mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

@media (min-width: 1024px) {
  .nav-mobile-toggle {
    display: none;
  }
}

.nav-mobile {
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}

.nav-mobile.open {
  transform: translateX(0);
}

.nav-mobile-inner {
  padding: 1.5rem;
}

.nav-mobile-link {
  display: block;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--primary-dark);
  padding: 1rem 0;
  border-bottom: 1px solid var(--border-light);
}

.nav-mobile-accordion {
  border-bottom: 1px solid var(--border-light);
}

.nav-mobile-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--primary-dark);
  cursor: pointer;
}

.nav-mobile-accordion-icon {
  transition: transform var(--transition-base);
}

.nav-mobile-accordion.open .nav-mobile-accordion-icon {
  transform: rotate(180deg);
}

.nav-mobile-accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.nav-mobile-accordion.open .nav-mobile-accordion-body {
  max-height: 500px;
}

.nav-mobile-accordion-body a {
  display: block;
  padding: 0.75rem 0 0.75rem 1.5rem;
  font-size: 0.9375rem;
  color: var(--neutral-dark-gray);
}

.nav-mobile-accordion-body a:hover {
  color: var(--accent-gold);
}

/* ========================================
   HERO SECTION
   ======================================== */
.hero {
  position: relative;
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  margin-top: 72px;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(10, 22, 40, 0.88) 0%,
    rgba(10, 22, 40, 0.72) 50%,
    rgba(1, 42, 45, 0.65) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: 3rem 1.5rem;
}

.hero-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  margin-bottom: 1.5rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 600;
  color: var(--white);
  line-height: 1.15;
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 2rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* ========================================
   ANNOUNCEMENT BANNER
   ======================================== */
.announcement-banner {
  background-color: var(--primary-green);
  color: var(--white);
  padding: 0.875rem 1.5rem;
}

.announcement-banner-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  text-align: center;
}

@media (min-width: 768px) {
  .announcement-banner-inner {
    flex-direction: row;
    gap: 1.5rem;
  }
}

.announcement-banner-text {
  font-size: 0.9375rem;
  font-weight: 500;
}

.announcement-banner-link {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent-gold);
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
}

.announcement-banner-link:hover {
  color: #DDB73A;
}

/* ========================================
   SECTION HEADERS
   ======================================== */
.section-header {
  margin-bottom: 3rem;
}

.section-header.center {
  text-align: center;
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  margin-bottom: 1rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  font-weight: 600;
  color: var(--primary-dark);
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.0625rem;
  color: var(--neutral-dark-gray);
  max-width: 600px;
}

/* ========================================
   FEATURED INSIGHTS
   ======================================== */
.insights-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .insights-row {
    grid-template-columns: repeat(3, 1fr);
  }
}

.insight-card {
  position: relative;
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: 2px;
  overflow: hidden;
  transition: box-shadow var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
}

.insight-card-image {
  aspect-ratio: 16 / 9;
  background: linear-gradient(135deg, var(--dark-teal), var(--primary-green));
  position: relative;
  overflow: hidden;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10, 22, 40, 0.4), transparent);
}

.insight-card-body {
  padding: 1.25rem;
}

.insight-card-tag {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-gold);
  margin-bottom: 0.5rem;
}

.insight-card-title {
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--primary-dark);
  line-height: 1.4;
}

/* ========================================
   ABOUT STATEMENT
   ======================================== */
.about-section {
  background-color: var(--off-white);
}

.about-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.about-text {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.625rem);
  font-weight: 400;
  line-height: 1.6;
  color: var(--primary-dark);
  margin-bottom: 2rem;
}

/* ========================================
   WHAT WE DO — VERTICAL TABS
   ======================================== */
.what-we-do {
  background-color: var(--white);
}

.tabs-vertical {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .tabs-vertical {
    grid-template-columns: 280px 1fr;
  }
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  border-left: 2px solid var(--border-light);
}

.tab-btn {
  position: relative;
  padding: 1rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--neutral-gray);
  text-align: left;
  transition: color var(--transition-base);
  border: none;
  background: none;
}

.tab-btn::before {
  content: '';
  position: absolute;
  left: -2px;
  top: 0;
  bottom: 0;
  width: 2px;
  background-color: transparent;
  transition: background-color var(--transition-base);
}

.tab-btn:hover {
  color: var(--primary-dark);
}

.tab-btn.active {
  color: var(--primary-dark);
}

.tab-btn.active::before {
  background-color: var(--accent-gold);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateX(10px); }
  to { opacity: 1; transform: translateX(0); }
}

.tab-panel-title {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 600;
  color: var(--primary-dark);
  margin-bottom: 1rem;
}

.tab-panel-text {
  font-size: 1.0625rem;
  color: var(--neutral-dark-gray);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* ========================================
   NEWSLETTER
   ======================================== */
.newsletter-section {
  background-color: var(--primary-dark);
  color: var(--white);
}

.newsletter-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .newsletter-inner {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}

.newsletter-title {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 600;
  color: var(--white);
  margin-bottom: 0.5rem;
}

.newsletter-subtitle {
  color: rgba(255, 255, 255, 0.7);
}

/* ========================================
   LATEST INSIGHTS
   ======================================== */
.latest-insights-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .latest-insights-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.latest-insight-card {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.latest-insight-image {
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, var(--dark-teal), var(--primary-green));
  border-radius: 2px;
  position: relative;
  overflow: hidden;
}

.latest-insight-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--neutral-gray);
}

.latest-insight-meta .divider {
  width: 1px;
  height: 12px;
  background-color: var(--border-light);
}

.latest-insight-title {
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--primary-dark);
  line-height: 1.4;
}

.latest-insight-date {
  font-size: 0.8125rem;
  color: var(--neutral-gray);
}

/* ========================================
   COMMITMENT PILLARS
   ======================================== */
.commitment-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .commitment-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.commitment-card {
  padding: 2rem;
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: 2px;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.commitment-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.commitment-card-title {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--primary-dark);
  margin-bottom: 0.75rem;
}

.commitment-card-text {
  font-size: 0.9375rem;
  color: var(--neutral-dark-gray);
  line-height: 1.6;
  margin-bottom: 1rem;
}

.commitment-card-link {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent-gold);
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
}

.commitment-card-link:hover {
  color: #B8941F;
}

/* ========================================
   SERVICE CATEGORIES GRID
   ======================================== */
.services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .services-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.service-card {
  padding: 2rem;
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: 2px;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
  display: flex;
  flex-direction: column;
}

.service-card:hover {
